139	    public String getPostcode() {
140	        return this.postcode;
141	    }
142	
143	    public void setPostcode(String postcode) {
144	        this.postcode = postcode;
145	    }
146	
147	    /**
148	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
149	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
150	     */
151	    @Transient
152	    public String getDisplayName() {
153	        return this.getLastName() + ", " + this.getFirstName();
154	    }
155	
156	    /**
157	     * The owner's initials: the upper-cased first letters of firstName and lastName,
158	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
159	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
160	     */
161	    @Transient
162	    public String getInitials() {
163	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
164	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
165	    }
166	
167	    /**
168	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
169	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
170	     * (e.g. {@code 'LON-SMI-0007-M26'}).
171	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
172	     */
173	    @Transient
174	    public String getMembershipNumber() {
175	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
176	    }
177	
178	    /**
179	     * The owner's numeric membership level, fixed at creation. Starts at {@code 1}; adds {@code 1}
180	     * when an {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
181	     * namesakeCount} is {@code 0}; capped at {@code 3} (level {@code 4} is reserved for tenure).
182	     * Not persisted — derived from {@link #getEmail()} and {@link #getNamesakeCount()}.
183	     */
184	    @Transient
185	    public int getMembershipLevel() {
186	        int level = 1;
187	        boolean hasEmail = this.email != null && !this.email.isBlank();
188	        if (hasEmail) {
189	            level++;
190	        }
191	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
192	        if (uniqueName) {
193	            level++;
194	        }
195	        return Math.min(level, 3);
196	    }
