198	    /**
199	     * Fixed city-to-region table used as the fall-back when deriving
200	     * {@link #getLocality() locality}.
201	     */
202	    private static final Map<String, String> CITY_REGION = Map.of(
203	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
204	
205	    /**
206	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
207	     * deriving {@link #getLocality() locality} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
208	     */
209	    private static final Map<String, int[]> REGION_RANGE = Map.of(
210	        "NSW", new int[] {2000, 2099},
211	        "VIC", new int[] {3000, 3099},
212	        "QLD", new int[] {4000, 4099});
213	
214	    /**
215	     * The owner's locality: the canonical region derived first from {@link #getPostcode()
216	     * postcode} by range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the
217	     * fixed {@link #CITY_REGION} city table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when
218	     * the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
219	     * Preferring the postcode disambiguates cities that share a name. Not persisted — derived
220	     * from {@link #getPostcode()} and {@link #getCity()}.
221	     */
222	    @Transient
223	    public String getLocality() {
224	        String region = regionFromPostcode();
225	        if (region != null) {
226	            return region;
227	        }
228	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
229	    }
230	
231	    /** Region whose range contains this owner's postcode, or {@code null} when the postcode is
232	     * absent, not 4 digits, or in no known range. */
233	    private String regionFromPostcode() {
234	        if (this.postcode == null || !this.postcode.matches("[0-9]{4}")) {
235	            return null;
236	        }
237	        int value = Integer.parseInt(this.postcode);
238	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
239	            int[] range = entry.getValue();
240	            if (value >= range[0] && value <= range[1]) {
241	                return entry.getKey();
242	            }
243	        }
244	        return null;
245	    }
246	
247	    /**
248	     * Whether more than 80 owners had already been created today when this response was
249	     * built. Not persisted — populated for the response by the create and fetch pipelines
250	     * and defaults to {@code false} so every owner serialization carries the flag.
251	     */
252	    @Transient
253	    public boolean isBulkSignupWarning() {
254	        return this.bulkSignupWarning;
255	    }
256	
257	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
258	        this.bulkSignupWarning = bulkSignupWarning;
259	    }
260	
261	    /**
262	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
263	     * is present, otherwise {@code 'PHONE'}.
264	     * Not persisted — derived from {@link #getEmail()}.
265	     */
266	    @Transient
267	    public String getContactPreference() {
268	        boolean hasEmail = this.email != null && !this.email.isBlank();
269	        return hasEmail ? "EMAIL" : "PHONE";
270	    }
271	
272	    protected Set<Pet> getPetsInternal() {
273	        if (this.pets == null) {
274	            this.pets = new HashSet<>();
275	        }
276	        return this.pets;
277	    }
278	
279	    protected void setPetsInternal(Set<Pet> pets) {
280	        this.pets = pets;
281	    }
282	
283	    public List<Pet> getPets() {
284	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
285	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
286	        return Collections.unmodifiableList(sortedPets);
287	    }
288	
289	    public void setPets(List<Pet> pets) {
290	        this.pets = new HashSet<>(pets);
291	    }
292	
293	    public void addPet(Pet pet) {
294	        getPetsInternal().add(pet);
295	        pet.setOwner(this);
296	    }
297	
298	    /**
299	     * Return the Pet with the given name, or null if none found for this Owner.
300	     *
301	     * @param name to test
302	     * @return true if pet name is already in use
303	     */
304	    public Pet getPet(String name) {
305	        return getPet(name, false);
306	    }
307	
308	    /**
309	     * Return the Pet with the given name, or null if none found for this Owner.
310	     *
311	     * @param name to test
312	     * @return true if pet name is already in use
313	     */
314	    public Pet getPet(String name, boolean ignoreNew) {
315	        name = name.toLowerCase();
316	        for (Pet pet : getPetsInternal()) {
317	            if (!ignoreNew || !pet.isNew()) {
318	                String compName = pet.getName();
319	                compName = compName.toLowerCase();
320	                if (compName.equals(name)) {
321	                    return pet;
322	                }
323	            }
324	        }
325	        return null;
326	    }
327	
328	    public Pet getPet(Integer petId) {
329	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
330	    }
331	
332	    @Override
333	    public String toString() {
334	        return new ToStringCreator(this)
335	
336	            .append("id", this.getId())
337	            .append("new", this.isNew())
338	            .append("lastName", this.getLastName())
339	            .append("firstName", this.getFirstName())
340	            .append("address", this.address)
341	            .append("city", this.city)
342	            .append("telephone", this.telephone)
343	            .toString();
344	    }
345	}
